{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Brigatinib, an oral kinase inhibitor with an anilinopyrimidine/piperazine motif similar to the query, has a measured absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral small-molecule anticancer drug with basic heteroaromatic nitrogen, has a measured absolute oral bioavailability of 72.7% in patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, an oral kinase inhibitor, has a microtracer-confirmed absolute oral bioavailability of 72.3% in patients with solid tumours, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, an oral kinase inhibitor, is almost completely absorbed with a mean absolute bioavailability of 98% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, an oral small-molecule drug with complete absorption and negligible first-pass extraction, has high oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Tacrolimus, the highest-similarity retrieved analogue, has an oral bioavailability of approximately 20–25% in patients, at or above the 20% threshold and therefore not contradictory to high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oral pyridopyrimidinone-type kinase inhibitor with a piperazine side chain. Retrieved direct human absolute bioavailability measurements for structurally related oral kinase inhibitors and heteroaromatic drugs are consistently ≥46% (brigatinib 46%, niraparib 73%, trametinib 72%, imatinib 98%, risdiplam high), and the highest-similarity analogue is at the 20–25% boundary. No affirmative evidence supports F < 20%, so the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself was retrieved; all evidence is from analogues with Morgan similarity <0.4.",
    "One retrieved record (mCPP) reports a wide F range of 12–84% and is not structurally transferable; it does not provide affirmative evidence for low F.",
    "Some records are predicted rather than experimentally measured (e.g., C24), so they were given less weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

